<template>
  <div class="home-view">
    <NavBarVue />
    <b-row class="mt-2">
      <b-col lg="3">
        <b-card
          :header="
            'Próximos pagamentos: ' + filterLoans(upcomingInstallments).length
          "
          header-tag="header"
          class="text-success"
        >
          <b-overlay :show="isLoading" rounded="sm">
            <p
              class="text-danger"
              v-if="filterLoans(upcomingInstallments).length == 0"
            >
              Sem nenhuma prestação pendente
            </p>
            <table v-else class="table table-sm table-hover table-stripped">
              <tbody>
                <tr
                  v-for="upcomingInstallment in filterLoans(
                    upcomingInstallments
                  )"
                  :key="upcomingInstallment.id"
                  style="font-size: 9pt; cursor: pointer"
                  class="text-success"
                  @click="openCustomerPanel(upcomingInstallment.accountNumber)"
                >
                  <td>{{ getCustomer(upcomingInstallment.accountNumber) }}</td>
                  <td
                    class="text-right"
                    v-money-format="upcomingInstallment.installment"
                  ></td>
                  <td class="text-right">
                    faltam
                    {{ calculateDays(upcomingInstallment.dueDate) * -1 }} dias
                  </td>
                </tr>
              </tbody>
            </table>
          </b-overlay>
        </b-card>
      </b-col>
      <b-col>
        <b-row>
          <b-col>
            <b-card
              class="text-center text-secondary"
              header-tag="header"
              :title="customers.length + ''"
            >
              <b-card-text
                ><b-icon icon="people-fill" style="font-size: 32pt"></b-icon>
                &nbsp;&nbsp;&nbsp;<b>MUTUÁRIOS</b></b-card-text
              >
              <b-button to="/customers" block variant="secondary" size="sm"
                >Ver todos</b-button
              >
            </b-card>
          </b-col>
          <b-col>
            <b-card
              class="text-center text-secondary"
              header-tag="header"
              :title="users.length + ''"
            >
              <b-card-text
                ><b-icon icon="people-fill" style="font-size: 32pt"></b-icon>
                &nbsp;&nbsp;&nbsp;<b>USUÁRIOS</b></b-card-text
              >
              <b-button to="/settings" block variant="secondary" size="sm"
                >Ver todos</b-button
              >
            </b-card>
          </b-col>
          <b-col>
            <b-card
              :header="
                'Prestações vencidas: ' + filterLoans(dueInstallments).length
              "
              header-tag="header"
              class="text-danger"
            >
              <b-overlay :show="isLoading" rounded="sm">
                <p
                  class="text-danger"
                  v-if="filterLoans(dueInstallments).length == 0"
                >
                  Sem nenhuma prestação pendente
                </p>
                <table v-else class="table table-sm table-hover table-stripped">
                  <tbody>
                    <tr
                      v-for="installment in filterLoans(dueInstallments)"
                      :key="installment.id"
                      style="font-size: 9pt; cursor: pointer"
                      class="text-danger"
                      @click="openCustomerPanel(installment.accountNumber)"
                    >
                      <td>{{ getCustomer(installment.accountNumber) }}</td>
                      <td
                        class="text-right"
                        v-money-format="installment.installment"
                      ></td>
                      <td class="text-right">
                        {{ calculateDays(installment.dueDate) }} dias de atrazo
                      </td>
                    </tr>
                  </tbody>
                </table>
              </b-overlay>
              <b-button
                to="/settings"
                block
                variant="danger"
                size="sm"
                :disabled="filterLoans(dueInstallments).length == 0"
                >Baixar prestações pendentes</b-button
              >
            </b-card>
          </b-col>
        </b-row>
      </b-col>
    </b-row>
    <!-- <b-row>
      <b-col cols="12">
        <h4 class="text-center">Últimos Movimentos</h4>
      </b-col>
    </b-row> -->
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import NavBarVue from "@/components/NavBar";
import moment from "moment";
import FilterCustomer from "@/utils/filterCustomer";

export default {
  data: () => ({
    today: moment(),
  }),

  components: {
    NavBarVue,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "users",
      "token",
      "company",
      "accounts",
      "customers",
      "dueInstallments",
      "upcomingInstallments",
      "updatedPassword",
    ]),
  },

  created() {
    this.checkPasswordStatus();
  },

  methods: {
    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },

    calculateDays(dueDate) {
      const diffDays = this.today.diff(dueDate, "days");
      return diffDays;
    },

    calculatePendingDays(dueDate) {
      const diffDays = this.today.diff(dueDate, "days");
      return diffDays;
    },

    openCustomerPanel(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      this.$store.commit("SET_CURRENT_CUSTOMER", filteredCustomer[0]);
      this.$router.replace("/customer");
    },

    filterLoans(amortizations) {
      const filteredLoansAmortization = amortizations.filter((a) => {
        return a.status == 0;
      });
      return filteredLoansAmortization;
    },

    getCustomer(accountNumber) {
      return FilterCustomer.filter(this.customers, accountNumber).customerName;
    },
  },
};
</script>
<style scoped></style>
